DELETE FROM questions WHERE topic = 'The Musculoskeletal System' AND subtopic IN ('Muscle Types & Characteristics', 'Sarcomere Structure');

-- Q1 [Muscle Types & Characteristics] easy skill1 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Musculoskeletal System', 'Muscle Types & Characteristics', 'A histology student examines a stained skeletal muscle fiber under the light microscope and notes that it contains many nuclei pressed against the inner edge of the cell membrane. Which feature of this fiber most directly accounts for this nuclear arrangement?', '[{"label": "A", "text": "Fusion of many myoblasts, whose nuclei remain at the periphery"}, {"label": "B", "text": "A single, centrally located nucleus from one myocyte"}, {"label": "C", "text": "Failure of precursor myoblasts to fuse, leaving one nucleus"}, {"label": "D", "text": "Myoblast nuclei migrating to the fiber''s central core"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is A because a skeletal muscle fiber is multinucleated with peripheral nuclei as a direct result of the fusion of many myoblasts whose individual nuclei are conserved at the cell''s edge. During development, many smaller myoblast cells fuse to form a mature muscle fiber, and the nucleus of each contributing myoblast remains intact in the mature cell, imparting the multinucleate characteristic (lines 5045-5046, 18210-18212). Under the light microscope these fibers appear striated with many nuclei squeezed along the membranes, that is, on their periphery (lines 7107, 7135). The continuous shared cytoplasm of the fused syncytium leaves the conserved nuclei displaced toward the sarcolemma rather than gathered centrally. (Choice A) is correct: myoblast fusion conserves each precursor''s nucleus, and these many nuclei sit at the periphery of the long fiber, which is exactly the arrangement observed. (Choice B) describes a cardiomyocyte, which is a single cell typically with a single centrally located nucleus (lines 7113-7114), not the many peripheral nuclei of a skeletal fiber. (Choice C) describes smooth and cardiac muscle, whose cells are not multinucleate because the myoblasts that form them do not fuse (line 18221); a skeletal fiber instead results from extensive fusion. (Choice D) reverses the actual outcome of fusion: the conserved myoblast nuclei remain at the periphery of the fiber, not migrating to a central core (lines 7135, 18211-18212). This is a Knowledge of Scientific Concepts and Principles question because you must recall that skeletal muscle fibers are multinucleated with peripheral nuclei as a direct consequence of myoblast fusion.', 'easy', '3B', 'Organ Systems', 'biology', 1, 75)
  RETURNING id
)
